    internal class AutosizeConverter : JsonConverter<Autosize>
    {
        public override bool CanConvert(Type t) => t == typeof(Autosize);

        public override Autosize Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            switch (reader.TokenType)
            {
                case JsonTokenType.String:
                    var stringValue = reader.GetString();
                    switch (stringValue)
                    {
                        case "pad":
                            return new Autosize { Enum = AutosizeType.Pad };
                        case "fit":
                            return new Autosize { Enum = AutosizeType.Fit };
                        case "none":
                            return new Autosize { Enum = AutosizeType.None };
                    }
                    break;
                case JsonTokenType.StartObject:
                    var objectValue = JsonSerializer.Deserialize<AutoSizeParams>(ref reader, options);
                    return new Autosize { AutoSizeParams = objectValue };
            }
            throw new JsonException("Cannot unmarshal type Autosize");
        }

        public override void Write(Utf8JsonWriter writer, Autosize value, JsonSerializerOptions options)
        {
            if (value.Enum != null)
            {
                switch (value.Enum)
                {
                    case AutosizeType.Pad:
                        JsonSerializer.Serialize(writer, "pad", options);
                        return;
                    case AutosizeType.Fit:
                        JsonSerializer.Serialize(writer, "fit", options);
                        return;
                    case AutosizeType.None:
                        JsonSerializer.Serialize(writer, "none", options);
                        return;
                }
            }
            if (value.AutoSizeParams != null)
            {
                JsonSerializer.Serialize(writer, value.AutoSizeParams, options);
                return;
            }
            throw new NotSupportedException("Cannot marshal type Autosize");
        }

        public static readonly AutosizeConverter Singleton = new AutosizeConverter();
    }

